const TZ = 'Europe/Prague';
const MAILBOX = 'personal';
const OWN = 'lukas.cypra@gmail.com';

function yamlQuote(s) {
  return JSON.stringify(String(s || '').replace(/\n/g, ' '));
}
function headerOf(msg, name) {
  const want = String(name).toLowerCase();
  const headers = (msg && msg.payload && msg.payload.headers) || msg.headers || [];
  if (Array.isArray(headers)) {
    const row = headers.find((h) => String(h.name || '').toLowerCase() === want);
    return row ? String(row.value || '') : '';
  }
  if (headers && typeof headers === 'object') {
    for (const [k, v] of Object.entries(headers)) {
      if (String(k).toLowerCase() === want) return String(v || '');
    }
  }
  // simplified thread message fields
  return String(msg[name] || msg[name && name.replace(/(^|-)(\w)/g, (_, a, b) => b.toUpperCase())] || '');
}
function decodeBody(msg) {
  const payload = msg.payload || msg;
  const chunks = [];
  function walk(p) {
    if (!p) return;
    if (p.body && p.body.data) {
      try {
        const b64 = String(p.body.data).replace(/-/g, '+').replace(/_/g, '/');
        chunks.push(Buffer.from(b64, 'base64').toString('utf8'));
      } catch (e) {}
    }
    if (Array.isArray(p.parts)) p.parts.forEach(walk);
  }
  walk(payload);
  let text = chunks.join('\n').trim();
  if (!text) text = String(msg.snippet || msg.text || '').trim();
  // strip html lightly
  if (/<html|<div|<br/i.test(text) && !text.includes('\n\n')) {
    text = text.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+\n/g, '\n').trim();
  }
  return text || '_(prázdné tělo)_';
}
function addr(msg, field) {
  return headerOf(msg, field) || (msg[field] && (msg[field].text || msg[field])) || '';
}

const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const j = item.json;
  // thread get returns {id, messages:[...]} or simplified messages list
  let threadId = String(j.id || j.threadId || '').trim();
  let messages = j.messages;
  if (!messages && j.threadId && j.id && !j.historyId) {
    // single message from getAll — skip here, thread node feeds us
    continue;
  }
  if (!Array.isArray(messages)) messages = [j];
  if (!threadId) threadId = String((messages[0] && (messages[0].threadId || messages[0].thread_id)) || '').trim();
  if (!threadId || seen.has(threadId)) continue;
  seen.add(threadId);

  const parts = [];
  let subject = '';
  let firstFrom = '';
  let lastDate = '';
  for (const m of messages) {
    const sub = headerOf(m, 'subject') || m.Subject || m.subject || '';
    const from = headerOf(m, 'from') || m.From || (m.from && m.from.text) || '';
    const to = headerOf(m, 'to') || m.To || (m.to && m.to.text) || '';
    const date = headerOf(m, 'date') || m.Date || m.date || '';
    if (!subject && sub) subject = sub;
    if (!firstFrom && from) firstFrom = from;
    if (date) lastDate = date;
    const body = decodeBody(m);
    parts.push(`### ${date || '?'}\n**From**: ${from}\n**To**: ${to}\n\n${body}\n`);
  }
  subject = subject || 'no-subject';
  const filename = `sb-${MAILBOX}-${threadId}.md`;
  const fm = [
    '---',
    'source: email',
    `mailbox: ${MAILBOX}`,
    `gmail_thread_id: ${yamlQuote(threadId)}`,
    `from: ${yamlQuote(firstFrom)}`,
    `subject: ${yamlQuote(subject)}`,
    `date: ${yamlQuote(lastDate)}`,
    '---',
    '',
  ].join('\n');
  const md = fm + `# Email: ${subject}\n\n**Mailbox**: ${MAILBOX}\n**Thread**: ${threadId}\n\n` + parts.join('\n---\n\n');
  out.push({ json: { filename, content: md, threadId, mailbox: MAILBOX, unstar: true } });
}
return out;

const formatted = $('Format thread → Markdown').all();
const searches = $input.all();
const out = [];
for (let i = 0; i < formatted.length; i++) {
  const f = formatted[i].json;
  // collect matching search hits for this filename from any search items
  const hits = searches.filter((s) => String(s.json.name || '') === f.filename);
  const fileId = hits.length ? String(hits[0].json.id || '') : '';
  out.push({ json: { ...f, existingFileId: fileId } });
}
return out;

const staticData = $getWorkflowStaticData('global');
const labels = $input.all().map((i) => i.json);
let found = labels.find((l) => String(l.name || '') === 'SB Saved');
if (found) {
  staticData.sbSavedLabelId = found.id;
  return [{ json: { labelId: found.id, created: false } }];
}
return [{ json: { labelId: '', needCreate: true } }];

const staticData = $getWorkflowStaticData('global');
let labelId = staticData.sbSavedLabelId || '';
// prefer freshly created
for (const item of $input.all()) {
  if (item.json.id && item.json.name === 'SB Saved') labelId = item.json.id;
  if (item.json.labelId) labelId = item.json.labelId;
}
if (labelId) staticData.sbSavedLabelId = labelId;
const threads = $('Pair file id').all();
return threads.map((t) => ({
  json: {
    threadId: t.json.threadId,
    labelId,
    unstar: !!t.json.unstar,
  },
}));
